window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":5.7},{"id":"n03","text":"All the police have is a blurry photo of the robber.","at":11.9,"t0":5.95,"t1":8.715},{"id":"n03a","text":"All he has is you.","at":17.93,"t0":8.965,"t1":10.075},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":20.75,"t0":10.375,"t1":13.295},{"id":"n03b","text":"But do you really remember? Because for you, it was just another Tuesday.","at":29.19,"t0":14.595,"t1":18.48},{"id":"f01","text":"Please, think! We were at the chai stall, in the rain! You had ginger chai! You paid twenty rupees!","at":38.66,"t0":19.33,"t1":25.11},{"id":"f01r","text":"Don't you remember?","at":50.82,"t0":25.41,"t1":26.695},{"id":"n04","text":"And now you do.","at":53.99,"t0":26.995,"t1":28},{"id":"o02","text":"He says you two were at a chai stall. So what did you drink?","at":56.7,"t0":28.35,"t1":31.945},{"id":"o03","text":"How much did you pay?","at":66.29,"t0":33.145,"t1":34.815},{"id":"o04","text":"Same as his statement.","at":71.83,"t0":35.915,"t1":37.945},{"id":"n06","text":"Everything you know about that night, he told you.","at":77.29,"t0":38.645,"t1":41.045},{"id":"n06b","text":"So where was he, really?","at":83.49,"t0":41.745,"t1":42.975},{"id":"n07","text":"He was here.","at":87.75,"t0":43.875,"t1":44.7},{"id":"o05","text":"Alibi confirmed. He can go.","at":92.4,"t0":46.2,"t1":48.75},{"id":"n08","text":"You just set a robber free.","at":98.5,"t0":49.25,"t1":50.625},{"id":"f02","text":"Next time, I'll pay.","at":103.25,"t0":51.625,"t1":52.96},{"id":"o06","text":"Oh, one more thing. That chaiwala at the stall, was he young or old?","at":107.12,"t0":53.56,"t1":57.71},{"id":"n12","text":"You can see him, can't you?","at":118.22,"t0":59.11,"t1":60.51},{"id":"n13","text":"But nobody even mentioned him until that question, and your brain still gave him a face.","at":121.72,"t0":60.86,"t1":65.65},{"id":"n14","text":"One question did that, so go do this to a friend.","at":132.7,"t0":66.35,"t1":69.12}];
